-- A single very long INSERT on one line, so that a small chunk size lands
-- boundaries inside strings, escapes and the statement terminator.
DROP TABLE IF EXISTS `chunky`;
CREATE TABLE `chunky` (
  `id` int NOT NULL,
  `v` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
